#!/bin/bash
set -e

# Optometry / Doctor module changes:
# - Removed full Latin form (Oculus Dexter/Sinister) everywhere in the
#   Optometry workspace and doctor's Examination tab Gonioscopy -- now
#   reads 'Right Eye (OD)' / 'Left Eye (OS)', matching the convention
#   already used elsewhere in the Examination tab.
# - Examination tab: 'C>D Ratio' -> 'C.D Ratio' (matches print, which
#   already used the dot notation).
# - Added Applanation Tonometry section (Right/Left eye pressure, mmHg)
#   directly after Posterior Segment in the doctor's Examination tab,
#   and on the printed OPD Case Sheet in the same position.
# - Gonioscopy collapsed from two passes (Without/With Dilation) to a
#   single pass -- on screen and on the printed case sheet. Legacy
#   staged records are read correctly (falls back to whichever pass
#   has data) so nothing already recorded is lost.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/consultation/[id]"
echo "" | base64 -d > "app/consultation/[id]/examination-tab.js"
echo "Wrote app/consultation/[id]/examination-tab.js"

mkdir -p "app/(main)/optometry/[id]"
echo "" | base64 -d > "app/(main)/optometry/[id]/optometry-workspace.js"
echo "Wrote app/(main)/optometry/[id]/optometry-workspace.js"

mkdir -p "app/print-templates"
echo "" | base64 -d > "app/print-templates/actions.js"
echo "Wrote app/print-templates/actions.js"

git add "app/consultation/[id]/examination-tab.js" "app/(main)/optometry/[id]/optometry-workspace.js" "app/print-templates/actions.js"
git commit -m "Optometry/Examination: short OD/OS labels, C.D notation, single-pass Gonioscopy, Applanation Tonometry field + print"
git push

echo "Done."
